    const card = this.add.rectangle(0, 0, W, H, 0x1e1e2e, 1);
    card.setStrokeStyle(2, 0x888888);

    // 제목
    const title = this.add.text(0, -H / 2 + 22, '설정', {
      fontSize: '18px', color: '#ffffff', fontStyle: 'bold',
    }).setOrigin(0.5);

