1	import Phaser from 'phaser';
2	
3	export default class Player extends Phaser.Physics.Arcade.Sprite {
4	  private cursors!: Phaser.Types.Input.Keyboard.CursorKeys;
5	  private speed: number;
6	  private baseSpeed: number; // 기본 속도 저장
7	  private texturePrefix: string;
8	  private leftKeyDown: boolean = false;
9	  private rightKeyDown: boolean = false;
10	  private readonly onKeyDown: (e: KeyboardEvent) => void;
11	  private readonly onKeyUp: (e: KeyboardEvent) => void;
12	
13	  // 현재 텍스처 방향 캐시 — setTexture를 매 프레임 호출하지 않기 위해
14	  private currentDir: string = 'front';
15	
16	  // 아이템 효과 상태
17	  private isInvincible: boolean = false;
18	  private speedBoostActive: boolean = false;
19	
20	  // 효과 타이머
21	  private invincibleTimer?: Phaser.Time.TimerEvent;
22	  private speedBoostTimer?: Phaser.Time.TimerEvent;
23	  private rainbowTimer?: Phaser.Time.TimerEvent;
24	
25	  constructor(scene: Phaser.Scene, x: number, y: number, speed: number = 300, texturePrefix: string = '') {
26	    // 기본 텍스처는 front (정면)
27	    super(scene, x, y, `${texturePrefix}front`);
28	    this.speed = speed;
29	    this.baseSpeed = speed; // 기본 속도 저장
30	    this.texturePrefix = texturePrefix;
31	
