protected async showGameOverUI(isNewRecord: boolean) {
  const W = this.scale.width;
  const H = this.scale.height;
  const cx = W / 2;
  // 반투명 검정 배경 추가 (가독성 향상)
  this.add.rectangle(cx, H / 2, W, H, 0x000000, 0.7).setDepth(200);

  // SKOR 제출 (백그라운드, 모든 모드에서 실행)
  // 새 기록 시: 이니셜 입력 영역(y≈380) 아래에 배치 / 일반 시: 개인최고(y≈320) 아래에 배치
  const skorStatusY = isNewRecord ? H / 2 + 118 : H / 2 + 80;
  const skorStatusText = this.add.text(cx, skorStatusY, '💰 SKOR 정제 중...', {
    fontSize: '16px',
    color: '#aaaaaa',
    stroke: '#000',
    strokeThickness: 2,
  }).setOrigin(0.5).setDepth(200);

  this.submitSkorOnGameOver(skorStatusText);

  if (isNewRecord) {
    // === 새 기록 달성 시: 상단에 배치 ===
    // 게임 오버 타이틀
    this.add.text(cx, H / 2 - 220, 'GAME OVER', {
      fontSize: '48px',
      color: '#ff0000',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 6
    }).setOrigin(0.5).setDepth(200);

    // 최종 점수
    this.add.text(cx, H / 2 - 150, `점수: ${this.score}`, {
      fontSize: '32px',
      color: '#ffffff',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 4
    }).setOrigin(0.5).setDepth(200);

    // 새 기록 메시지
    this.add.text(cx, H / 2 - 100, '🎉 개인 신기록 🎉', {
      fontSize: '28px',
      color: '#FFD700',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 4
    }).setOrigin(0.5).setDepth(200);

    // 이니셜 입력 UI 표시
    this.showInitialInputUI();
  } else {
    // === 새 기록 미달성 시: 중앙에 배치 ===
    // 게임 오버 타이틀
    this.add.text(cx, H / 2 - 120, 'GAME OVER', {
      fontSize: '48px',
      color: '#ff0000',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 6
    }).setOrigin(0.5).setDepth(200);

    // 최종 점수
    this.add.text(cx, H / 2 - 40, `점수: ${this.score}`, {
      fontSize: '32px',
      color: '#ffffff',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 4
    }).setOrigin(0.5).setDepth(200);

    // 로컬 최고 점수
    this.add.text(cx, H / 2 + 20, `개인 최고: ${this.highScore}`, {
      fontSize: '24px',
      color: '#FFD700',
      stroke: '#000000',
      strokeThickness: 3
    }).setOrigin(0.5).setDepth(200);

    // 재시작 안내
    this.showRestartButton(false);
  }
}

