    // Vercel Preview 툴바 등 외부 스크립트가 ArrowLeft/Right를 가로채도 우선 실행됨
    window.addEventListener('keydown', this.onKeyDown, { capture: true });
    window.addEventListener('keyup', this.onKeyUp, { capture: true });

    // 터치/마우스를 캔버스 DOM 이벤트로 직접 추적
    // — scene.input.on() 을 쓰면 Phaser 내부 입력 파이프라인과 충돌해 게임오브젝트
    //   pointerdown(버튼 등)이 무시되는 버그가 발생하므로 DOM 레벨에서 처리
    const canvas = scene.game.canvas;

    const getGameX = (clientX: number): number => {
      const rect = canvas.getBoundingClientRect();
      return (clientX - rect.left) * (scene.scale.width / rect.width);
    };

    const applyDir = (gameX: number) => {
      const cx = scene.scale.width / 2;
      this.touchLeft  = gameX < cx;
      this.touchRight = gameX > cx;
    };

    this.onTouchStart = (e: TouchEvent) => {
      if (e.touches.length > 0) applyDir(getGameX(e.touches[0].clientX));
    };
    this.onTouchEnd = () => { this.touchLeft = false; this.touchRight = false; };
    this.onTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) applyDir(getGameX(e.touches[0].clientX));
    };
    this.onMouseDown = (e: MouseEvent) => { applyDir(getGameX(e.clientX)); };
    this.onMouseUp   = () => { this.touchLeft = false; this.touchRight = false; };
    this.onMouseMove = (e: MouseEvent) => {
      if (e.buttons > 0) applyDir(getGameX(e.clientX));
    };

    canvas.addEventListener('touchstart',  this.onTouchStart, { passive: true });
    canvas.addEventListener('touchend',    this.onTouchEnd);
    canvas.addEventListener('touchcancel', this.onTouchEnd);
    canvas.addEventListener('touchmove',   this.onTouchMove,  { passive: true });
    canvas.addEventListener('mousedown',   this.onMouseDown);
    canvas.addEventListener('mouseup',     this.onMouseUp);
    canvas.addEventListener('mousemove',   this.onMouseMove);

    // shutdown은 restart/stop/destroy 시 항상 먼저 호출됨 → 한 번만 등록으로 충분
    scene.events.once('shutdown', this.removeListeners, this);
  }

  private removeListeners() {
    window.removeEventListener('keydown', this.onKeyDown, { capture: true });
    window.removeEventListener('keyup', this.onKeyUp, { capture: true });
    const canvas = this.scene.game.canvas;
    canvas.removeEventListener('touchstart',  this.onTouchStart);
    canvas.removeEventListener('touchend',    this.onTouchEnd);
    canvas.removeEventListener('touchcancel', this.onTouchEnd);
    canvas.removeEventListener('touchmove',   this.onTouchMove);
    canvas.removeEventListener('mousedown',   this.onMouseDown);
    canvas.removeEventListener('mouseup',     this.onMouseUp);
    canvas.removeEventListener('mousemove',   this.onMouseMove);
  }

  update() {
    let isMoving = false;
    let nextDir: string = this.currentDir;

    // 좌우 이동 (Phaser 키보드 OR window 레벨 키보드 둘 다 체크)
    if (this.cursors.left.isDown || this.leftKeyDown) {
      this.setVelocityX(-this.speed);
      nextDir = 'left';
      isMoving = true;
    } else if (this.cursors.right.isDown || this.rightKeyDown) {
      this.setVelocityX(this.speed);
      nextDir = 'right';
      isMoving = true;
    } else {
      this.setVelocityX(0);
    }

    if (this.touchLeft) {
      this.setVelocityX(-this.speed);
      nextDir = 'left';
      isMoving = true;
    } else if (this.touchRight) {
      this.setVelocityX(this.speed);
      nextDir = 'right';
      isMoving = true;
    }

    // 멈춰있을 때는 정면 이미지
    if (!isMoving && this.body?.velocity.x === 0) {
      nextDir = 'front';
    }

    // 방향이 실제로 바뀔 때만 setTexture 호출 (매 프레임 호출 방지)
    if (nextDir !== this.currentDir) {
      this.setTexture(`${this.texturePrefix}${nextDir}`);
      this.currentDir = nextDir;
    }
  }

  // 헤르메스 신발 효과: 10초간 속도 2배 증가
  activateSpeedBoost(duration: number = 10000) {
    // 기존 타이머가 있으면 제거
    if (this.speedBoostTimer) {
      this.speedBoostTimer.remove();
    }

    // 속도 증가 (2배)
    this.speedBoostActive = true;
    this.speed = this.baseSpeed * 2;

    // 시각적 피드백: 노란색 틴트
    this.setTint(0xffff00);

    // 일정 시간 후 원래 속도로 복구
    this.speedBoostTimer = this.scene.time.addEvent({
      delay: duration,
      callback: () => {
        this.speedBoostActive = false;
        this.speed = this.baseSpeed;
        // 무적이 아니면 틴트 제거
        if (!this.isInvincible) {
          this.clearTint();
        } else {
          // 무적 효과만 남김
          this.setTint(0x00ffff);
        }
      },
      callbackScope: this
    });
  }

  // 무지개 별 효과: 5초간 무적
  activateInvincibility(duration: number = 5000) {
    // 기존 타이머가 있으면 제거
    if (this.invincibleTimer) {
      this.invincibleTimer.remove();
    }
    if (this.rainbowTimer) {
      this.rainbowTimer.remove();
    }

    // 무적 활성화
    this.isInvincible = true;

    // 무지개 색상 배열 (빨주노초파남보)
    const rainbowColors = [
      0xff0000, // 빨강
      0xff7700, // 주황
      0xffff00, // 노랑
      0x00ff00, // 초록
      0x00ffff, // 하늘
      0x0000ff, // 파랑
      0xff00ff  // 보라
    ];

    let colorIndex = 0;

    // 무지개 색상 순환 효과 (150ms마다 색상 변경)
    this.rainbowTimer = this.scene.time.addEvent({
      delay: 150,
      callback: () => {
        this.setTint(rainbowColors[colorIndex]);
        colorIndex = (colorIndex + 1) % rainbowColors.length;
      },
      callbackScope: this,
      loop: true
    });

    // 일정 시간 후 무적 해제
    this.invincibleTimer = this.scene.time.addEvent({
      delay: duration,
      callback: () => {
        this.isInvincible = false;
        // 무지개 타이머 정지
        if (this.rainbowTimer) {
          this.rainbowTimer.remove();
          this.rainbowTimer = undefined;
        }
        // 속도 증가가 아니면 틴트 제거
        if (!this.speedBoostActive) {
          this.clearTint();
        } else {
          // 속도 증가 효과만 남김
          this.setTint(0xffff00);
        }
      },
      callbackScope: this
    });
  }

  // 무적 상태 확인
  getIsInvincible(): boolean {
    return this.isInvincible;
  }

  // 시각 효과 없는 단순 무적 (센티넬 보호막 흡수용)
  setInvincibleBriefly(duration: number): void {
    if (this.invincibleTimer) {
      this.invincibleTimer.remove();
    }
    this.isInvincible = true;
    this.invincibleTimer = this.scene.time.addEvent({
      delay: duration,
      callback: () => { this.isInvincible = false; },
      callbackScope: this,
    });
  }

  // 효과 정리 (씬 종료 시)
  cleanupEffects() {
    if (this.speedBoostTimer) {
      this.speedBoostTimer.remove();
    }
    if (this.invincibleTimer) {
      this.invincibleTimer.remove();
    }
    if (this.rainbowTimer) {
      this.rainbowTimer.remove();
    }
  }
}

