    // 기존 타이머가 있으면 제거
    if (this.invincibleTimer) {
      this.invincibleTimer.remove();
    }
    if (this.rainbowTimer) {
      this.rainbowTimer.remove();
    }

    // 무적 활성화
    this.isInvincible = true;

    // 무지개 색상 배열 (빨주노초파남보)
    const rainbowColors = [
      0xff0000, // 빨강
      0xff7700, // 주황
      0xffff00, // 노랑
      0x00ff00, // 초록
      0x00ffff, // 하늘
      0x0000ff, // 파랑
      0xff00ff  // 보라
    ];

    let colorIndex = 0;

    // 무지개 색상 순환 효과 (150ms마다 색상 변경)
